   <main class="page">
     <section class="card">
       <p class="eyebrow">Preferences</p>
       <h1>Choose your notification channel</h1>
       <p class="intro">Set the way you want to hear from us so updates arrive where they are most useful.</p>

       <form id="notification-form">
         <div class="form-field" role="group" aria-labelledby="notification-question">
           <div id="notification-question" class="question">How do you prefer to receive notifications?</div>

           <label class="option">
             <input type="radio" name="notificationPreference" value="Email" required>
             <span>Email</span>
           </label>

           <label class="option">
             <input type="radio" name="notificationPreference" value="SMS">
             <span>SMS</span>
           </label>

           <label class="option">
             <input type="radio" name="notificationPreference" value="Push Notifications">
             <span>Push Notifications</span>
           </label>
         </div>

         <div class="actions">
           <button type="submit">Submit</button>
           <p id="form-message" class="message" aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById("notification-form");
     const message = document.getElementById("form-message");

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const selectedOption = form.querySelector('input[name="notificationPreference"]:checked');
       message.textContent = selectedOption
         ? "Preference saved: " + selectedOption.value
         : "Please choose one option before submitting.";
     });
   </script>
